styles.css:
html.prism-on-serifMode body, html.prism-on-serifMode .mw-body { font-family: Georgia, 'Source Serif Pro', serif !important; }
html.prism-mod-wikipedia-tweaks .mw-page-container { max-width: var(--prism-contentWidth, 900px) !important; }
html.prism-on-sepiaMode body { background: #f4ecd8 !important; filter: sepia(0.25); }
html.prism-on-sepiaMode .vector-body { background: #fbf6e9 !important; }
html.prism-on-hideDonate .frb, html.prism-on-hideDonate .banner-container, html.prism-on-hideDonate #siteNotice { display: none !important; }
html.prism-on-hideSidebar .vector-sidebar, html.prism-on-hideSidebar #mw-panel { display: none !important; }
html.prism-on-hideSidebar .mw-body { margin-left: 0 !important; }
